param([string]$EnvFile='.\.env')
$ErrorActionPreference='Stop'
$v=@{};Get-Content $EnvFile|Where-Object{$_-match'^[^#].*='}|ForEach-Object{$p=$_-split'=',2;$v[$p[0].Trim()]=$p[1].Trim()}
foreach($n in @('GK_SITE_URL','GK_CONTROL_TOKEN','GK_UNIFIED_API_TOKEN')){if([string]::IsNullOrWhiteSpace($v[$n])){throw "$n fehlt."}}
$site=$v.GK_SITE_URL.TrimEnd('/');$control=@{Authorization='Bearer '+$v.GK_CONTROL_TOKEN};$unified=@{Authorization='Bearer '+$v.GK_UNIFIED_API_TOKEN}
function New-Svg([string]$heading,[string]$subheading,[string]$type){
 $body=switch($type){
  'copper' {'<path d="M150 315H430M770 315H1050" stroke="#c87818" stroke-width="18"/><rect x="430" y="210" width="340" height="210" rx="24" fill="#fff4df" stroke="#c87818" stroke-width="7"/><g stroke="#0b3558" stroke-width="8"><line x1="500" y1="260" x2="700" y2="360"/><line x1="500" y1="360" x2="700" y2="260"/></g><text x="600" y="470" text-anchor="middle" font-family="Arial,sans-serif" font-size="24" fill="#34556f">Kupfer-Doppelader und Verteilpunkt</text>'}
  'build' {'<path d="M145 390H1055" stroke="#00a6c8" stroke-width="16"/><path d="M760 390V235L900 145L1040 235V390" fill="#e8f7fb" stroke="#0b3558" stroke-width="7"/><rect x="875" y="300" width="70" height="90" fill="#ffffff" stroke="#0b3558" stroke-width="6"/><rect x="175" y="235" width="240" height="155" rx="18" fill="#0b3558"/><text x="295" y="325" text-anchor="middle" font-family="Arial,sans-serif" font-size="30" font-weight="700" fill="#ffffff">Netz</text><circle cx="600" cy="390" r="34" fill="#ffffff" stroke="#00a6c8" stroke-width="10"/><text x="600" y="465" text-anchor="middle" font-family="Arial,sans-serif" font-size="24" fill="#34556f">Trasse, Hauseinführung und Übergabepunkt</text>'}
