  'component' {'<path d="M155 315H445" stroke="#f4c542" stroke-width="22"/><path d="M755 315H1045" stroke="#f4c542" stroke-width="22"/><rect x="445" y="225" width="310" height="180" rx="26" fill="#e8f7fb" stroke="#0b3558" stroke-width="7"/><circle cx="525" cy="315" r="30" fill="#00a6c8"/><circle cx="675" cy="315" r="30" fill="#00a6c8"/><line x1="555" y1="315" x2="645" y2="315" stroke="#0b3558" stroke-width="12"/><text x="600" y="455" text-anchor="middle" font-family="Arial,sans-serif" font-size="24" fill="#34556f">Faser, Steckverbinder und Spleißstelle</text>'}
  'measure' {'<polyline points="120,375 220,375 270,260 330,445 410,300 485,375 570,375 620,245 680,430 760,315 840,375 1080,375" fill="none" stroke="#00a6c8" stroke-width="13" stroke-linejoin="round"/><line x1="120" y1="455" x2="1080" y2="455" stroke="#0b3558" stroke-width="5"/><g font-family="Arial,sans-serif" font-size="23" fill="#34556f"><text x="145" y="500">Leitungsanfang</text><text x="870" y="500">Anschluss</text></g><circle cx="620" cy="245" r="18" fill="#c87818"/>'}
  'service' {'<rect x="150" y="215" width="360" height="250" rx="24" fill="#e8f7fb" stroke="#0b3558" stroke-width="7"/><g stroke="#00a6c8" stroke-width="10" fill="none"><path d="M210 285l25 25 55-65"/><path d="M210 365l25 25 55-65"/></g><g stroke="#0b3558" stroke-width="7"><line x1="325" y1="280" x2="450" y2="280"/><line x1="325" y1="360" x2="450" y2="360"/></g><path d="M680 425l95-170 55 32-95 170z" fill="#c87818" stroke="#0b3558" stroke-width="6"/><circle cx="835" cy="235" r="62" fill="#ffffff" stroke="#0b3558" stroke-width="7"/><path d="M875 275l105 105" stroke="#0b3558" stroke-width="18"/>'}
  'provider' {'<circle cx="240" cy="305" r="92" fill="#0b3558"/><circle cx="600" cy="305" r="92" fill="#00a6c8"/><circle cx="960" cy="305" r="92" fill="#c87818"/><g stroke="#34556f" stroke-width="13"><line x1="332" y1="305" x2="508" y2="305"/><line x1="692" y1="305" x2="868" y2="305"/></g><g font-family="Arial,sans-serif" font-size="28" font-weight="700" fill="#ffffff" text-anchor="middle"><text x="240" y="315">Netz A</text><text x="600" y="315">Open</text><text x="960" y="315">Netz B</text></g><text x="600" y="455" text-anchor="middle" font-family="Arial,sans-serif" font-size="24" fill="#34556f">Anbieter, Infrastruktur und offener Netzzugang</text>'}
  'wifi' {'<circle cx="600" cy="405" r="34" fill="#0b3558"/><path d="M455 350a205 205 0 01290 0M390 285a295 295 0 01420 0M325 220a385 385 0 01550 0" fill="none" stroke="#00a6c8" stroke-width="18" stroke-linecap="round"/><g font-family="Arial,sans-serif" font-size="28" font-weight="700" fill="#0b3558"><text x="260" y="480">2,4 GHz</text><text x="535" y="480">5 GHz</text><text x="810" y="480">6 GHz</text></g>'}
 }
 return '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630" role="img"><rect width="1200" height="630" fill="#f4f8fb"/><rect x="45" y="45" width="1110" height="540" rx="28" fill="#ffffff" stroke="#0b3558" stroke-width="4"/><text x="85" y="115" font-family="Arial,sans-serif" font-size="42" font-weight="700" fill="#0b3558">'+$heading+'</text><text x="85" y="158" font-family="Arial,sans-serif" font-size="24" fill="#34556f">'+$subheading+'</text>'+$body+'</svg>'
}
$groups=@(
 @{key='kupfer-leitungsweg';heading='Kupfer-Leitungsweg';sub='Vom Hauptkabel über den Verteilpunkt bis zum Haus';type='copper';alt='Schematischer Kupfer-Leitungsweg mit Kabel und Verteilpunkt.';ids=@(3012,5003)},
 @{key='glasfaser-ausbauweg';heading='Glasfaser-Ausbauweg';sub='Trasse, Hauseinführung und Anschluss im Gebäude';type='build';alt='Schematischer Glasfaser-Ausbauweg vom Netz bis ins Gebäude.';ids=@(1007,3023,3024,3025,4009,4010,14002,14003,16008,16009,18011,18012)},
 @{key='pon-komponenten';heading='PON-Komponenten';sub='OLT, passiver Splitter und Teilnehmeranschlüsse';type='pon';alt='Schematische PON-Struktur mit OLT, Splitter und ONTs.';ids=@(4002,4003,19001,19002)},
 @{key='glasfaser-komponenten';heading='Glasfaser-Komponenten';sub='Faser, Verbindung und sauberer optischer Übergang';type='component';alt='Schematische Glasfaser mit Steckverbinder und Spleißstelle.';ids=@(4008,19005,19006,19007)},
 @{key='dsl-leitungsmessung';heading='DSL-Leitungsmessung';sub='Signalverlauf, Störungen und Leitungsqualität einordnen';type='measure';alt='Schematischer Signalverlauf einer DSL-Leitungsmessung.';ids=@(7004,7005,7007,7008,7009,9003,11002,11003,13004,13005,17010,20798,20800)},
 @{key='techniker-fehlersuche';heading='Techniker-Fehlersuche';sub='Prüfen, messen und den Fehlerabschnitt eingrenzen';type='service';alt='Schematische Checkliste und Messwerkzeug für die technische Fehlersuche.';ids=@(9006,12005,17005,17007,17012)},
 @{key='anbieter-netzzugang';heading='Anbieter und Netzzugang';sub='Infrastruktur, Kooperation und Open Access unterscheiden';type='provider';alt='Schematische Darstellung verbundener Netze und offenen Netzzugangs.';ids=@(18003,18005,18006,18008,18009)},
 @{key='wlan-frequenzbaender';heading='WLAN-Frequenzbänder';sub='Reichweite und Datenrate passend zum Einsatz wählen';type='wifi';alt='Schematische WLAN-Funkwellen für 2,4, 5 und 6 Gigahertz.';ids=@(8005)}
)
$root=if(Test-Path(Join-Path $PSScriptRoot '..\GkProductionWorker.sln')){Split-Path -Parent $PSScriptRoot}else{$PSScriptRoot};$backup=Join-Path $root('backups\featured-batch-'+(Get-Date -Format 'yyyyMMdd-HHmmss'));New-Item $backup -ItemType Directory -Force|Out-Null;$rows=@()
foreach($g in $groups){$filename='gk-'+$g.key+'.svg';$mediaResults=@(Invoke-RestMethod($site+'/wp-json/wp/v2/media?search='+$g.key+'&per_page=20&_fields=id,source_url,date')-TimeoutSec 30);$existing=@($mediaResults|Where-Object{$_.source_url-match[regex]::Escape($filename)}|Sort-Object date -Descending);if($existing.Count){$json=$existing|ConvertTo-Json -Depth 5 -Compress;$m=[regex]::Match($json,'"id":(\d+)');if(-not$m.Success){throw "Medien-ID nicht lesbar: $($g.key)"};$attachmentId=[long]$m.Groups[1].Value}else{$svg=New-Svg $g.heading $g.sub $g.type;$payload=@{filename=$filename;title=$g.heading;alt=$g.alt;svg=$svg}|ConvertTo-Json -Compress;$upload=Invoke-RestMethod($site+'/wp-json/gk-control/v1/media/upload-svg') -Method Post -Headers $control -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($payload));$attachmentId=[long]$(if($upload.attachment_id){$upload.attachment_id}elseif($upload.media_id){$upload.media_id}else{$upload.id});if($attachmentId-le 0){throw "Upload ohne ID: $($g.key)"}}
 Write-Host("GRUPPE: $($g.key) | Attachment=$attachmentId")
 foreach($id in $g.ids){$kind='posts';try{$before=Invoke-RestMethod($site+"/wp-json/wp/v2/posts/$id" + '?_fields=id,featured_media')-TimeoutSec 30}catch{$kind='pages';$before=Invoke-RestMethod($site+"/wp-json/wp/v2/pages/$id" + '?_fields=id,featured_media')-TimeoutSec 30};$oldId=[long]$before.featured_media;if($oldId-ne$attachmentId){$row=[pscustomobject]@{id=$id;group=$g.key;old_attachment=$oldId;new_attachment=$attachmentId};$rows+=$row;$row|Export-Csv (Join-Path $backup 'featured-image-backup.csv') -NoTypeInformation -Encoding UTF8 -Append;$setPayload=@{post_id=$id;attachment_id=$attachmentId}|ConvertTo-Json -Compress;$setResult=Invoke-RestMethod($site+'/wp-json/gk-control/v1/media/set-featured') -Method Post -Headers $control -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($setPayload));};$check=$null;for($attempt=1;$attempt-le 8;$attempt++){Start-Sleep -Seconds 1;$check=Invoke-RestMethod($site+"/wp-json/wp/v2/$kind/$id" + '?_fields=id,featured_media&_gk_check='+(Get-Date -Format 'HHmmssfff'))-TimeoutSec 30;if([long]$check.featured_media-eq$attachmentId){break}};if([long]$check.featured_media-ne$attachmentId){throw "Zuweisung nicht verifiziert: $id | Erwartet=$attachmentId | Aktuell=$($check.featured_media) | Antwort=$($setResult|ConvertTo-Json -Compress)"};Write-Host("${id}: VERIFIED | Gruppe=$($g.key) | Attachment=$attachmentId")}
}
$rows|Export-Csv (Join-Path $backup 'featured-image-backup.csv') -NoTypeInformation -Encoding UTF8;$cache=Invoke-RestMethod($site+'/wp-json/gk-unified-api/v1/clear-cache') -Method Post -Headers $unified -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes('{}'));if($cache.cache_cleared-ne$true){throw 'Cache nicht geleert'};Write-Host('FERTIG: Geändert='+$rows.Count+' | Verifiziert='+($groups.ids|ForEach-Object{$_}|Measure-Object).Count+' | Backup='+$backup)
